const SITE_PATHS = ['/team', '/our-team', '/people', '/leadership', '/about', '/about-us', '/company', '/who-we-are', '/our-people', '/about/team', '/team/'];
const NAME_STOP = /^(our|the|team|about|contact|read|more|learn|view|meet|join|careers?|jobs?|news|blog|press|privacy|terms|home|portfolio|investments?|capital|partners?|ventures?|advisors?|advisory|leadership|management|board|senior|managing|general|vice|chief|head|director|principal|associate|analyst|founder|co-founder|president|follow|linkedin|twitter|email|profile|bio|all|new|latest|why|what|who|how|we|us|get|know|investor|investors|fund|funds|india|global|group|office|offices|insights|resources|events|business|private|equity|limited|ltd|llp|pvt|inc|corporate|finance|banking|consulting|strategy|operations|growth|product|talent|people|culture|values|mission|vision|story|history|startups?|companies|company|services|solutions|technology|technologies|digital|financial|research|sustainability|diversity|inclusion|subscribe|submit|apply|search|menu|login|sign|up|in|of|and|for|to|at|by)$/i;
const TITLE_RE = /(partner|principal|vice president|\bvp\b|associate|analyst|director|manager|founder|head of|\bhead\b|chief|president|consultant|recruit|talent|investor|investment|officer|\bmd\b|managing|lead\b|engagement|strategist|product|growth|operations)/i;
const tokOk = (t) => /^([A-Z][a-z][A-Za-z'’\-]*|[A-Z]\.)$/.test(t);
function goodName(s) {
  s = String(s || '').replace(/\s+/g, ' ').trim().replace(/^(dr|mr|ms|mrs)\.?\s+/i, '');
  const t = s.split(' ');
  if (t.length < 2 || t.length > 4) return '';
  if (!t.every(tokOk) || t.filter((x) => x.length > 2).length < 2) return '';
  if (t.some((x) => NAME_STOP.test(x.replace(/[.,]/g, '')))) return '';
  return s;
}
const decodeHtml = (s) => s.replace(/&nbsp;|&#160;/g, ' ').replace(/&amp;/g, '&').replace(/&#8217;|&rsquo;|&#39;|&apos;/g, "'").replace(/&#8211;|&ndash;|&#8212;|&mdash;/g, '-').replace(/&quot;|&#8220;|&#8221;/g, '"').replace(/&#(\d+);/g, (m, n) => String.fromCharCode(Number(n)));
function htmlLines(html) {
  const txt = String(html || '').replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>|<noscript[\s\S]*?<\/noscript>|<svg[\s\S]*?<\/svg>|<!--[\s\S]*?-->/gi, ' ')
    .replace(/<[^>]+>/g, '\n');
  const out = [];
  for (const l of decodeHtml(txt).split(/\n+/)) { const t = l.replace(/\s+/g, ' ').trim(); if (t && t !== out[out.length - 1]) out.push(t); }
  return out;
}
// returns [{ name, title }] found on one page
function extractPeople(html) {
  const found = new Map();
  const add = (n, t) => { const name = goodName(n); const title = String(t || '').replace(/\s+/g, ' ').trim(); if (name && title && title.length <= 90 && TITLE_RE.test(title) && !found.has(name)) found.set(name, title); };
  // 1) structured data many sites include: schema.org Person
  for (const m of String(html || '').matchAll(/<script[^>]+application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi)) {
    try {
      const walk = (o) => { if (!o || typeof o !== 'object') return; if (Array.isArray(o)) return o.forEach(walk);
        if (/Person/i.test(String(o['@type'])) && o.name) add(o.name, o.jobTitle); Object.values(o).forEach(walk); };
      walk(JSON.parse(m[1]));
    } catch (e) { /* ignore broken JSON */ }
  }
  // 2) visible text: "Name" followed by a job title line, or "Name - Title" / "Name, Title" on one line
  const L = htmlLines(html);
  for (let i = 0; i < L.length; i++) {
    const one = L[i].match(/^(.{4,40}?)\s*(?:,|\s[-–—|]\s)\s*(.{3,90})$/);
    if (one && goodName(one[1]) && TITLE_RE.test(one[2])) { add(one[1], one[2]); continue; }
    if (!goodName(L[i])) continue;
    for (let k = 1; k <= 3 && i + k < L.length; k++) {
      const nx = L[i + k];
      if (nx.length > 90 || goodName(nx)) break;
      if (TITLE_RE.test(nx)) { add(L[i], nx); break; }
    }
  }
  return [...found].map(([name, title]) => ({ name, title }));
}
