// everybody we can read off one firm's website (kept for the day, so a firm is only fetched once)
async function scanSite(c) {
  VSD.site = VSD.site || {};
  const host = c.domain;
  const hit = VSD.site[host];
  if (hit && hit.day === vToday) return hit;
  const res = { day: vToday, people: [], pages: 0 };
  VSD.site[host] = res;
  let base = '', home = '';
  for (const b of ['https://www.' + host, 'https://' + host]) { home = await getPage(b + '/'); if (home) { base = b; break; } }
  if (!base) return res;
  const urls = new Set();
  for (const m of home.matchAll(/href=["']([^"'#]+)["']/gi)) {
    if (!/(team|people|leadership|about|who-we-are|management|our-story)/i.test(m[1]) || /\.(pdf|jpe?g|png|svg|webp)(\?|$)/i.test(m[1])) continue;
    try { const u = new URL(m[1], base + '/'); if (u.hostname.replace(/^www\./, '') === host) urls.add(u.href.split('#')[0]); } catch (e) { /* bad link */ }
  }
  for (const p of SITE_PATHS) urls.add(base + p);
  const pages = [home].concat(await Promise.all([...urls].slice(0, 8).map(getPage)));
  const byName = new Map();
  for (const html of pages) { if (!html) continue; res.pages++; for (const p of extractPeople(html)) if (!byName.has(p.name)) byName.set(p.name, p); }
  res.people = [...byName.values()].map((p) => Object.assign(p, { url: base + '/' }));
  return res;
}
