  const hit = VSD.site[host];
  if (hit && hit.day === vToday) return hit;
  const res = { day: vToday, people: [], pages: 0 };
  VSD.site[host] = res;
  let base = '', home = '';
  for (const b of ['https://www.' + host, 'https://' + host]) { home = await getPage(b + '/'); if (home) { base = b; break; } }
  if (!base) return res;
