const GEMINI_PREFERRED = ['gemini-3.8-flash', 'gemini-3.6-flash', 'gemini-3.5-flash', 'gemini-3.5-flash-lite',
  'gemini-3.1-flash-lite', 'gemini-2.5-flash', 'gemini-flash-latest'];
const staticData = (() => { try { return $getWorkflowStaticData('global'); } catch (e) { return {}; } })();
let lastGemini = 0;
async function listGeminiModels() {
  try {
    const r = await http({ method: 'GET', url: S.gemini_base + '/v1beta/models', qs: { pageSize: 200 },
      headers: { 'x-goog-api-key': S.gemini_key } }, 2);
    return (r.models || [])
      .filter((m) => (m.supportedGenerationMethods || []).includes('generateContent'))
      .map((m) => String(m.name || '').replace(/^models\//, ''))
      .filter((n) => /flash/.test(n) && !/(tts|image|live|audio|embed|transcribe|robotics|computer|native|thinking)/.test(n));
  } catch (e) { notes.push('Could not list Gemini models: ' + errMsg(e)); return []; }
}
function rankModels(avail) {
  const pref = GEMINI_PREFERRED.filter((m) => avail.includes(m));
  const rest = avail.filter((m) => !pref.includes(m) && !/preview|exp/.test(m))
    .sort((a, b) => b.localeCompare(a, undefined, { numeric: true }));
  return pref.concat(rest);
}
async function geminiCall(model, prompt) {
  const r = await http({
    method: 'POST',
    url: S.gemini_base + '/v1beta/models/' + model + ':generateContent',
    headers: { 'x-goog-api-key': S.gemini_key, 'Content-Type': 'application/json' },
    body: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: { responseMimeType: 'application/json', temperature: 0.2 },
    },
  }, 4);
  const parts = (((r.candidates || [])[0] || {}).content || {}).parts || [];
  return parts.map((p) => p.text || '').join('');
}
async function gemini(prompt) {
  const gap = Number(S.gemini_gap_ms || 4500);
  const wait = lastGemini + gap - Date.now();
  if (wait > 0) await sleep(wait);
  lastGemini = Date.now();
  const wanted = String(S.gemini_model || 'auto');
  let candidates = [staticData.geminiModel, wanted !== 'auto' ? wanted : null].filter(Boolean);
  let listed = false;
  for (let i = 0; i < 8; i++) {
    if (!candidates.length) {
      if (listed) break;
      listed = true;
      const avail = await listGeminiModels();
      candidates = rankModels(avail);
      if (!candidates.length) candidates = GEMINI_PREFERRED.slice();
    }
    const model = candidates.shift();
    try {
      const text = await geminiCall(model, prompt);
      staticData.geminiModel = model;
      return parseJSON(text);
    } catch (e) {
      const code = statusOf(e);
      if (code === '404' || code === '400' && /not found|not supported|unknown model/i.test(errMsg(e))) {
        if (staticData.geminiModel === model) delete staticData.geminiModel;
        continue;
      }
      if (code === '401' || code === '403') throw new Error('Gemini rejected the key (' + code + '). Check GEMINI_KEY in keys.txt.');
      throw e;
    }
  }
  throw new Error('No Gemini model available for this key. Open aistudio.google.com and check the key works.');
}
function parseJSON(t) {
  try { return JSON.parse(t); } catch (e) {
    const m = String(t).match(/[\[{][\s\S]*[\]}]/);
    if (m) { try { return JSON.parse(m[0]); } catch (e2) { /* fall through */ } }
    throw new Error('The AI reply was not valid JSON. First part: ' + String(t).slice(0, 200));
  }
}

