const BLOCKED_RE = /block|spamhaus|blacklist|black list|listed|reputation|policy|not allowed|denied|5\.7\.\d|dynamic|residential|rbl|barracuda/i;
// One SMTP conversation: EHLO, MAIL FROM:<>, then RCPT TO for each address. Returns per-address code + text.
function smtpProbe(mx, addrs, timeoutMs) {
  return new Promise((resolve) => {
    const out = { codes: [], error: '', blocked: false };
    let buf = '', step = 0, done = false, sock;
    const finish = () => {
      if (done) return; done = true; clearTimeout(timer);
      try { sock.write('QUIT\r\n'); } catch (e) { /* ignore */ }
      try { sock.destroy(); } catch (e) { /* ignore */ }
      resolve(out);
    };
    const timer = setTimeout(() => { out.error = out.error || 'timeout'; finish(); }, timeoutMs);
    try { sock = net.createConnection({ port: Number(S.smtp_port || 25), host: mx }); } catch (e) { out.error = String(e.message); return finish(); }
    sock.setEncoding('utf8');
    sock.on('error', (e) => { out.error = String(e.code || e.message); finish(); });
    sock.on('close', () => { if (!done) { out.error = out.error || 'closed'; finish(); } });
    const send = (l) => { try { sock.write(l + '\r\n'); } catch (e) { out.error = 'write'; finish(); } };
    sock.on('data', (chunk) => {
      buf += chunk;
      // a reply is complete when a line starts with "NNN " (space, not dash)
      const m = buf.match(/(?:^|\r?\n)(\d{3}) [^\r\n]*\r?\n/);
      if (!m) return;
      const reply = buf; buf = '';
      const code = Number(m[1]);
      if (step === 0) { // greeting
        if (code !== 220) { out.error = 'greeting ' + code; out.blocked = BLOCKED_RE.test(reply); return finish(); }
        step = 1; return send('EHLO ' + (S.smtp_helo || 'lead-finder.local'));
      }
      if (step === 1) {
        if (code !== 250) { out.error = 'ehlo ' + code; out.blocked = BLOCKED_RE.test(reply); return finish(); }
        step = 2; return send('MAIL FROM:<' + (S.smtp_from || '') + '>');
      }
      if (step === 2) {
        if (code !== 250) { out.error = 'mailfrom ' + code; out.blocked = BLOCKED_RE.test(reply); return finish(); }
        step = 3; return send('RCPT TO:<' + addrs[0] + '>');
      }
      // RCPT replies
      out.codes.push({ code, text: reply.replace(/\s+/g, ' ').trim().slice(0, 160) });
      if (code >= 500 && BLOCKED_RE.test(reply) && !/user|mailbox|recipient|address|unknown|exist|not found|no such/i.test(reply)) { out.blocked = true; return finish(); }
      if (out.codes.length < addrs.length) return send('RCPT TO:<' + addrs[out.codes.length] + '>');
      finish();
    });
  });
}

function rnd() { return 'zq' + Math.random().toString(36).slice(2, 10) + 'x'; }
// returns { results: {addr: 'valid'|'invalid'|'unknown'}, catchAll: bool, usable: bool }
async function selfCheck(domain, addrs) {
  if (!net || S.smtp_selfcheck === false || String(S.smtp_selfcheck) === 'false') return { usable: false };
  const d = domInfo(domain);
  if (d.blockedDay === vToday) return { usable: false };
  const mx = await mxOf(domain);
  if (!mx) return { usable: false, noMx: true };
  VSD.sc = VSD.sc && VSD.sc.day === vToday ? VSD.sc : { day: vToday, n: 0 }; VSD.sc.n++;
  const probe = addrs.concat([rnd() + '@' + domain]);
  const r = await smtpProbe(mx, probe, Number(S.smtp_timeout_ms || 20000));
  if (r.blocked || (r.error && !r.codes.length)) {
    if (r.blocked) d.blockedDay = vToday;
    if (r.error) notes.push('Self-check ' + domain + ': ' + (r.blocked ? 'mail server refuses checks from this PC' : r.error));
    return { usable: false };
  }
  const res = {};
  addrs.forEach((a, i) => {
    const c = (r.codes[i] || {}).code;
    res[a] = !c ? 'unknown' : (c === 250 || c === 251) ? 'valid' : (c >= 550 && c <= 553) ? 'invalid' : 'unknown';
  });
  const rc = (r.codes[addrs.length] || {}).code;
  const catchAll = rc === 250 || rc === 251;
  if (rc) d.catchAll = catchAll;
  const anyKnown = Object.values(res).some((v) => v !== 'unknown');
  return { usable: anyKnown, results: res, catchAll };
}

