  const best = cands[0];
  if (!(await mxOf(domain))) return { email: '', status: 'LinkedIn only (no mail server found for ' + domain + ')' };
  if (d.catchAll === true && d.catchAllDay && (Date.now() - d.catchAllDay) < 30 * 864e5) return { email: best, status: 'Unverified (domain accepts all)' };

  // 1) free self-check (all patterns in one connection)
  const sc = await selfCheck(domain, cands.slice(0, Number(S.smtp_patterns || 6)));
  if (sc.usable) {
    if (sc.catchAll) { d.catchAll = true; d.catchAllDay = Date.now(); return { email: best, status: 'Unverified (domain accepts all)' }; }
    const hit = cands.find((a) => sc.results[a] === 'valid');
    if (hit) { d.pattern = patOf[hit]; return { email: hit, status: 'Verified (mail server check)', pattern: patOf[hit] }; }
    if (cands.slice(0, Number(S.smtp_patterns || 6)).every((a) => sc.results[a] === 'invalid')) return { email: '', status: 'No working address found - use LinkedIn' };
