  return null;
}
const liKey = (u) => String(u || '').toLowerCase().replace(/^https?:\/\/(\w+\.)?/, '').replace(/[?#].*$/, '').replace(/\/$/, '');

const companies = L.targets.filter((t) => t.track === TRACK);
sd.rot = sd.rot || {};
let idx = Number(sd.rot[TRACK] || 0);
const maxIdx = idx + companies.length * ROLE_SETS[TRACK].length;   // one full pass over every firm x role pair per day
let queries = 0;
const rows = [];
let verified = 0;
async function emailFor(p) {
  const nm = p.name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\b(dr|mr|ms|mrs|ca|cfa)\.?\s+/g, '').split(/[^a-z]+/).filter((s) => s.length > 1);
  let email = '', status = 'LinkedIn only';
  if (p.pattern !== 'none' && p.domain && nm.length) {
    try { const r = await findEmail(nm, p.domain, p.pattern); email = r.email; status = r.status; }
    catch (e) { notes.push('Email check: ' + errMsg(e).slice(0, 80)); }
    if (email && seenEmails.has(email.toLowerCase())) return null;
    if (email) seenEmails.add(email.toLowerCase());
  }
  if (status.startsWith('Verified')) verified++;
  return [L.today, TRACK, p.name, p.title, p.company, p.linkedin, email, status, p.domain, verified <= target && status.startsWith('Verified') ? 'Top ' + target : 'Extra'];
}
// rounds: a few searches -> check the new people's emails -> stop once the verified goal is met
async function rounds(limitQ) {
while (companies.length && verified < target && queries < limitQ && idx < maxIdx) {
  const people = [];
  for (let k = 0; k < 3 && queries < limitQ && idx < maxIdx; k++) {
    if (searchLeftNow() <= 0) { if (searchLeft() <= 0) notes.push('All search services used up for today'); break; }
    const c = companies[idx % companies.length];
    const pair = ROLE_SETS[TRACK][Math.floor(idx / companies.length) % ROLE_SETS[TRACK].length];
    idx++; queries++;
    sd.tavilyUsed = (sd.tavilyUsed || 0) + 1;
    const coQ = c.company.replace(/\s*\(.*\)/, '').replace(/\s+india$/i, '').trim();
    const res = await tavily(`"${coQ}" ("${pair[0]}" OR "${pair[1]}") India`, { max: 20, domains: ['linkedin.com'] });
    for (const x of res) {
      if (!/linkedin\.com\/in\//i.test(x.url)) continue;
      const key = liKey(x.url);
      if (seenLinks.has(key)) continue;
      const p = parseProfile(x, c);
      if (!p) continue;
      const roleText = coKeys(c).concat([c.company.replace(/\s*\(.*\)/, '').toLowerCase()]).sort((a, b) => b.length - a.length)
        .reduce((s, k) => s.replace(new RegExp(esc(k), 'gi'), ' '), p.roleText);   // "Partners" in a fund name is not a role
      if (!ROLE_OK[TRACK].test(roleText)) continue;
      if (NOT_ROLE.test(p.title)) continue;                                      // marketing, sales, engineering, interns ...
      seenLinks.add(key);
      people.push({ name: p.name, title: p.title, company: c.company, domain: c.domain, pattern: c.pattern, linkedin: x.url.split('?')[0] });
    }
  }
  if (!people.length && searchLeftNow() <= 0) break;
  // emails: free mail-server check, then free checker APIs, then Reoon - 4 people at a time
  for (let i = 0; i < people.length; i += 4) {
    const got = await Promise.all(people.slice(i, i + 4).map((p) => emailFor(p)));
    for (const r of got) if (r) rows.push(r);
  }
}
}
// (A) free searches that renew every month
holdOneTime(true);
try { await rounds(Math.min(maxQueries, Math.floor(searchLeftNow() / Math.max(tracksLeft, 1)))); } finally { holdOneTime(false); }
// ---- (B) the firms' own team pages (no search credits) + new firms that meet our cutoffs ----
const newFirms = [];
if (companies.length && verified < target && String(S.sitescan || 'on') !== 'off') {
  sd.siteDone = sd.siteDone || {}; sd.rot2 = sd.rot2 || {}; sd.firmsDay = sd.firmsDay || {};
  if (Object.keys(sd.siteDone).length > 20000) sd.siteDone = {};
  try {
    if (sd.firmsDay[TRACK] !== L.today && companies.length < Number(S.max_firms_per_track || 60)) {
      sd.firmsDay[TRACK] = L.today;
      const allDomains = new Set(L.targets.map((t) => t.domain).filter(Boolean));
      const found = await discoverFirms(TRACK, L.targets.filter((t) => t.track === TRACK).map((t) => t.company), allDomains, Number(S.new_firms_per_track || 8));
      for (const f of found) { companies.push(f); newFirms.push([f.track, f.company, f.domain, '', f.pattern, f.region]); }
    }
  } catch (e) { notes.push('New-firm finder failed: ' + errMsg(e).slice(0, 80)); }
  const capPeople = Number(S.sitescan_max_people || 80);
  let checked = 0, pagesRead = 0, namesFound = 0, i2 = 0;
  const start = Number(sd.rot2[TRACK] || 0);
  for (; i2 < companies.length && verified < target && checked < capPeople; i2++) {
    const c = companies[(start + i2) % companies.length];
    if (!c.domain) continue;
    let site;
    try { site = await scanSite(c); } catch (e) { continue; }
    pagesRead += site.pages;
    const fresh = site.people.filter((p) => ROLE_OK[TRACK].test(p.title) && !NOT_ROLE.test(p.title) && !sd.siteDone[p.name.toLowerCase() + '|' + c.domain]);
    namesFound += fresh.length;
    for (let k = 0; k < fresh.length && verified < target && checked < capPeople; k += 4) {
      const batch = fresh.slice(k, k + 4);
      batch.forEach((p) => { sd.siteDone[p.name.toLowerCase() + '|' + c.domain] = L.today; });
      checked += batch.length;
      const got = await Promise.all(batch.map((p) => emailFor({ name: p.name, title: p.title, company: c.company, domain: c.domain, pattern: c.pattern, linkedin: p.url })));
      for (const r of got) if (r && r[6]) rows.push(r);                // website people only count when we found an email
    }
  }
  sd.rot2[TRACK] = (start + i2) % Math.max(companies.length, 1);
  notes.push(`${TRACK}: company websites - read ${pagesRead} pages, ${namesFound} new people, ${newFirms.length} new firms`);
  sd.siteStats = sd.siteStats || {}; sd.siteStats[TRACK] = { day: L.today, pages: pagesRead, people: namesFound, checked };
}
// (C) still short of the goal: now use the one-time credits (Linkup, Serper)
if (verified < target && searchLeft() > 0) await rounds(queries + Math.max(0, Math.min(maxQueries - queries, Math.floor(searchLeft() / Math.max(tracksLeft, 1)))));
sd.rot[TRACK] = idx % Math.max(companies.length * ROLE_SETS[TRACK].length, 1);

// verified first, then guesses, then LinkedIn-only
const rank = (s) => (s.startsWith('Verified') ? 0 : s.startsWith('Unverified') ? 1 : 2);
rows.sort((a, b) => rank(a[7]) - rank(b[7]));
return [{ json: { peopleRows: rows, verified, queries, newFirms, peopleNotes: notes } }];
